public class LineNumbererTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static String call(String input) {
        try {
            return LineNumberer.numberLines(
                    new java.io.BufferedReader(new java.io.StringReader(input)));
        } catch (Exception e) {
            return "threw " + e.getClass().getSimpleName();
        }
    }

    public static void main(String[] args) {
        check("two lines", "1: first\n2: second", call("first\nsecond"));
        check("single line", "1: only", call("only"));
        check("three lines", "1: a\n2: b\n3: c", call("a\nb\nc"));
        check("blank middle line kept", "1: x\n2: \n3: y", call("x\n\ny"));
        check("trailing newline adds no extra line", "1: a\n2: b", call("a\nb\n"));
        check("empty input", "", call(""));
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
