public class LineNumberer {

    public static String numberLines(java.io.BufferedReader in)
            throws java.io.IOException {
        StringBuilder result = new StringBuilder();
        String line;
        int number = 1;
        while ((line = in.readLine()) != null) {
            if (number > 1) {
                result.append("\n");
            }
            result.append(number).append(": ").append(line);
            number++;
        }
        return result.toString();
    }
}
